import {$,$$,esc,openForm,field,toast} from './ui.js';
import {uid} from './storage.js';
import {crisHome} from './hub-links.js';
export {attachClue} from './clue-blocks.js';
import {attachClue} from './clue-blocks.js';
export async function openBoardClues(ctx,link,{onInsert}={}){
 try{await link.refresh();}catch(error){toast(error.message,true);return;}
 const target=ctx.scene(),campaign=link.campaign();let filter='',showAll=false;
 openForm({title:'Pistas do quadro · '+target.title,wide:true,body:`<p class="dialog-description">Prepare os documentos no quadro e marque “Só mestre” para mantê-los ocultos. Vincule uma pista ao roteiro: o botão inserido envia o comando de revelação ao quadro do mestre. A mesa precisa estar ao vivo para os jogadores receberem a mudança.</p><div class="board-link-tools"><a class="btn outline" href="${new URL('quadro/',crisHome()).href}" target="_blank" rel="noopener">Abrir quadro em outra tela ↗</a><button type="button" class="btn outline" id="refreshBoardClues">Atualizar pistas</button></div><label class="search-field"><input type="search" id="boardClueSearch" placeholder="Buscar pista…" aria-label="Buscar pista do quadro"></label><label class="dialog-description"><input type="checkbox" id="boardShowAll"> Mostrar todos os itens do quadro</label><div id="boardClueRows" class="board-clue-rows"></div>`,onReady:root=>{
  const render=()=>{$('#boardClueRows',root).innerHTML=link.items.filter(i=>(showAll||i.named)&&i.title.toLocaleLowerCase().includes(filter)).map(i=>`<article class="board-clue-row"><div><strong>${esc(i.title)}</strong><small>${i.hidden?'Oculta · só mestre':'Visível na mesa'} · ${esc(i.type)} · ${esc(i.id.slice(-6))}</small></div><button type="button" class="btn outline small" data-link-clue="${esc(i.id)}">Inserir neste ponto</button><button type="button" class="btn primary small" data-reveal-clue="${esc(i.id)}">Revelar agora</button></article>`).join('')||'<p class="empty-small">Nenhuma pista nomeada encontrada. No quadro, selecione um item, dê um nome em “Pista do roteiro” e marque “Mostrar na lista”. Aguarde “Quadro salvo na conta” e atualize aqui. Para acessar itens antigos, marque “Mostrar todos os itens do quadro”.</p>';
   $$('[data-link-clue]',root).forEach(b=>b.onclick=()=>{const item=link.items.find(i=>i.id===b.dataset.linkClue);if(!onInsert){toast('Abra a edição e escolha o ponto do texto para inserir a pista.');return;}$('#appDialog').close();attachClue(target,item,campaign,{insert:onInsert});toast('Pista inserida no ponto escolhido.');});
   $$('[data-reveal-clue]',root).forEach(b=>b.onclick=async()=>{b.disabled=true;try{await link.send(b.dataset.revealClue,'reveal',campaign);toast('Pedido de revelação enviado. O quadro do mestre aplicará a mudança.');}catch(error){toast(error.message,true);}finally{b.disabled=false;}});
  };
  $('#boardShowAll',root).onchange=e=>{showAll=e.target.checked;render();};$('#boardClueSearch',root).oninput=e=>{filter=e.target.value.toLocaleLowerCase();render();};$('#refreshBoardClues',root).onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await link.refresh();if($('#boardClueRows',root))render();}catch(error){toast(error.message,true);}finally{b.disabled=false;}};render();
 }});
}
